sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var env = new x_fed_day2_ops.Day2Env();
  if (!env.isTestMode()) { stepResult.setFailed('x_fed_day2_ops.test_mode must be true on a declared non-prod instance'); return; }

  var sam = new x_fed_day2_ops.SamCorrelationClient();

  var noId = sam.writeClosureSummary('', { closed: true });
  if (noId.ok) { stepResult.setFailed('writeClosureSummary should refuse with no sam_request_id'); return; }

  var ok = sam.writeClosureSummary('ATF-SAM-0008', { closed: true });
  if (!ok.ok || ok.method !== 'test_mode') { stepResult.setFailed('writeClosureSummary should return a canned success in test_mode: ' + JSON.stringify(ok)); return; }

  var forced = sam.writeClosureSummary('ATF-SAM-0008', { closed: true, _forceWritebackFailure: true });
  if (forced.ok) { stepResult.setFailed('the ATF-only _forceWritebackFailure hook should force a failure even in test_mode'); return; }

  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var enabled = gs.getProperty('x_fed_day2_ops.sam_closure_writeback', 'false') === 'true';
  if (enabled) {
    stepResult.setFailed('fixture drifted: x_fed_day2_ops.sam_closure_writeback is true on this instance — the opt-in-default assumption for this suite does not hold');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var lineage = sam.recordLineage(null, 'ATF-SAM-0009', 'atf-correlation-0009', {
    verified_by: 'pull-verify', verified_at: new GlideDateTime().getValue(),
    verified_authority: 'app-owner', verified_status: 'approved', verified_item: 'ATF-Test-Role'
  });
  if (!lineage.ok) { stepResult.setFailed('fixture lineage write failed: ' + JSON.stringify(lineage)); return; }

  var saved = gs.getProperty('x_fed_day2_ops.sam_closure_writeback', 'false');
  try {
    gs.setProperty('x_fed_day2_ops.sam_closure_writeback', 'true');

    var orch = new x_fed_day2_ops.MacdrOrchestrator();
    var request = {
      verb: 'Reset', control: 'IA-5', ksi: 'KSI-IAM-01',
      requester_id: gs.getUser().getID(),
      approver_id: 'day2-servicedesk-sysid',
      privileged: false,
      sam_request_id: 'ATF-SAM-0009'
    };
    var result = orch.run(
      request,
      function () { return { ok: true }; },
      { action: 'disableUser', target: { userId: 'test-user-0001' } }
    );

    if (!result.ok || result.clause !== 'closed') {
      stepResult.setFailed('expected the run to close: ' + JSON.stringify(result));
      return;
    }

    // The write-back itself is a fire-and-forget call inside the orchestrator
    // (see _writeSamClosureSummary) -- confirm the underlying call succeeds
    // for this exact sam_request_id, independent of the orchestrator's result.
    var wrote = sam.writeClosureSummary('ATF-SAM-0009', { closed: true });
    if (!wrote.ok) { stepResult.setFailed('writeClosureSummary should succeed (canned) for a valid id: ' + JSON.stringify(wrote)); return; }

    stepResult.setSuccess();
  } finally {
    gs.setProperty('x_fed_day2_ops.sam_closure_writeback', saved);
  }
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var lineage = sam.recordLineage(null, 'ATF-SAM-0010', 'atf-correlation-0010', {
    verified_by: 'pull-verify', verified_at: new GlideDateTime().getValue(),
    verified_authority: 'app-owner', verified_status: 'approved', verified_item: 'ATF-Test-Role'
  });
  if (!lineage.ok) { stepResult.setFailed('fixture lineage write failed: ' + JSON.stringify(lineage)); return; }

  var saved = gs.getProperty('x_fed_day2_ops.sam_closure_writeback', 'false');
  try {
    gs.setProperty('x_fed_day2_ops.sam_closure_writeback', 'true');

    var orch = new x_fed_day2_ops.MacdrOrchestrator();
    var request = {
      verb: 'Reset', control: 'IA-5', ksi: 'KSI-IAM-01',
      requester_id: gs.getUser().getID(),
      approver_id: 'day2-servicedesk-sysid',
      privileged: false,
      sam_request_id: 'ATF-SAM-0010',
      _forceWritebackFailure: true   // ATF-only -- see MacdrOrchestrator._writeSamClosureSummary
    };
    var result = orch.run(
      request,
      function () { return { ok: true }; },
      { action: 'disableUser', target: { userId: 'test-user-0001' } }
    );

    if (!result.ok || result.clause !== 'closed') {
      stepResult.setFailed('a forced SAM write-back failure must not prevent closure, got: ' + JSON.stringify(result));
      return;
    }
    stepResult.setSuccess();
  } finally {
    gs.setProperty('x_fed_day2_ops.sam_closure_writeback', saved);
  }
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var orch = new x_fed_day2_ops.MacdrOrchestrator();

  // 1. The key is on the reserved list at all.
  if (x_fed_day2_ops.MacdrOrchestrator.RESERVED.indexOf('_forcewritebackfailure') === -1) {
    stepResult.setFailed('_forceWritebackFailure must be on MacdrOrchestrator.RESERVED');
    return;
  }

  // 2. The detector finds it on a caller-supplied request object, case-insensitively.
  var hit = orch._reservedKeysIn({ verb: 'Change', _forceWritebackFailure: true });
  if (!hit.length) {
    stepResult.setFailed('_reservedKeysIn should flag a caller-supplied _forceWritebackFailure');
    return;
  }

  // 3. A clean request is not flagged — the guard must not refuse normal traffic.
  if (orch._reservedKeysIn({ verb: 'Change', ritm: 'RITM0012345' }).length) {
    stepResult.setFailed('_reservedKeysIn flagged an ordinary request');
    return;
  }

  // NOT COVERED HERE, by construction: the production refusal itself. run()
  // only refuses when test_mode is false, and this suite asserts test_mode is
  // true in step 100. Exercising it needs an instance with test_mode off —
  // see CURRENT-STATE-PDI-VALIDATION.md.
  stepResult.setSuccess();
})(outputs, steps, stepResult);
